SELECT id, host, level, latency_ms, status_code, context, FROM_JSON(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').user.tier AS tier, GET_JSON_OBJECT(payload_json, '$.user.id') AS user_id, COALESCE(context['version'], 'direct') AS version_or_default, GET_JSON_OBJECT(payload_json, '$.user.tier') AS user_tier, CAST((status_code & 2) != 0 AS INT) AS has_fault FROM app_logs WHERE status_code >= 332
